import React from 'react';
import {Composition} from 'remotion';
import {HelloWorld} from './compositions/HelloWorld';
import {Demo3D} from './compositions/Demo3D';
import {AudioVisualizer3D} from './compositions/AudioVisualizer3D';

// Matches the duration of the synthetic demo track generated by
// scripts/generate-demo-audio.mjs (12s @ 30fps). Real user-uploaded audio
// will use calculateMetadata() to derive this dynamically (Phase 2).
const DEMO_AUDIO_DURATION_IN_FRAMES = 12 * 30;

export const RemotionRoot: React.FC = () => {
  return (
    <>
      <Composition
        id="HelloWorld"
        component={HelloWorld}
        durationInFrames={90}
        fps={30}
        width={1280}
        height={720}
      />
      <Composition
        id="Demo3D"
        component={Demo3D}
        durationInFrames={150}
        fps={30}
        width={1280}
        height={720}
      />
      <Composition
        id="AudioVisualizer3D"
        component={AudioVisualizer3D}
        durationInFrames={DEMO_AUDIO_DURATION_IN_FRAMES}
        fps={30}
        width={1280}
        height={720}
      />
    </>
  );
};
